contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= value, "insufficient test balance");

        uint256 balBefore = address(c).balance;

        bool reverted;
        c.withdraw(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        bool callerIsOwner = address(this) == c.owner();
        uint256 balAfter = address(c).balance;

        assert(
            (!reverted) == (callerIsOwner && value <= balBefore) &&
            (reverted || balAfter == balBefore - value)
        );
    }

    receive() external payable {}
}

